def min_paint_to_color(n: int, m: int, k: int, colors: List[int], paints: List[List[int]]) -> int:
    def backtrack(index: int, current_beauty: int, current_cost: int) -> bool:
        if index == n:
            return current_beauty == k

        if colors[index] != 0:
            return backtrack(index + 1, current_beauty, current_cost)

        best_cost = float('inf')
        for color in range(1, m + 1):
            cost = paints[index][color - 1]
            new_beauty = current_beauty + 1 if colors[index - 1] != color else current_beauty
            if new_beauty <= k:
                best_cost = min(best_cost, backtrack(index + 1, new_beauty, current_cost + cost))

        return best_cost < float('inf')

    result = backtrack(0, 0, 0)
    return result if result != float('inf') else -1

